  if (payload['title']) lines.push(`title: ${String(payload['title'])}`);
  if (payload['site']) lines.push(`site: ${String(payload['site'])}`);
  if (payload['superseded']) lines.push(`superseded_by: ${String(payload['superseded_by'])}`);
  lines.push('');
  lines.push(String(payload['body'] ?? payload['text'] ?? ''));
  return lines.join('\n');
}

